        # Your code here
        max_len = 0
        n = len(s)
        for i in range(n):
            for j in range(i, n):
                # Check if substring s[i..j] is semi-repetitive
                # If it is, update max_len
                if self.is_semi_repetitive(s, i, j):
                    max_len = max(max_len, j - i + 1)
