    def is_semi_repetitive(self, s: str, i: int, j: int) -> bool:
        # Count the number of adjacent identical pairs in s[i..j]
        count = 0
        for k in range(i, j):
            if s[k] == s[k+1]:
                count += 1
                if count > 1:
                    return False
        return count <= 1
