class Solution:
    def relocateMarbles(self, nums: List[int], moveFrom: List[int], moveTo: List[int]) -> List[int]:
        # Initialize the marbles map
        marbles = defaultdict(int)
        for num in nums:
            marbles[num] += 1

        for i in range(len(moveFrom)):
            source = moveFrom[i]
            dest = moveTo[i]

            # If the source is not empty, move marbles
            if marbles[source] > 0:
                count = marbles[source]
                marbles[source] = 0
                marbles[dest] += count

        # Collect all the positions with at least one marble
        result = [pos for pos in marbles if marbles[pos] > 0]
        return sorted(result)
