class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        dp0 = [1] * n
        dp1 = [1] * n

        for i in range(1, n):
            # Choose nums1[i] for nums3[i]
            # Check if it is non-decreasing from nums3[i-1] (either nums1[i-1] or nums2[i-1])
            # If possible, extend the subarray
            if nums1[i] >= nums1[i-1]:
                dp0[i] = dp0[i-1] + 1
            if nums1[i] >= nums2[i-1]:
                dp0[i] = max(dp0[i], dp1[i-1] + 1)

            # Choose nums2[i] for nums3[i]
            if nums2[i] >= nums1[i-1]:
                dp1[i] = dp0[i-1] + 1
            if nums2[i] >= nums2[i-1]:
