class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        # Your code here
        n = len(s)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            for j in range(i):
                substr = s[j:i]
                if self.is_balanced(substr):
                    dp[i] = min(dp[i], dp[j] + 1)
        return dp[n]

    def is_balanced(self, substr: str) -> bool:
        # Check if the substring is balanced
        count = {}
        for c in substr:
            count[c] = count.get(c, 0) + 1
        values = list(count.values())
        if len(values) == 0:
            return True
        # Check if all values are the same
        first = values[0]
        for v in values:
            if v != first:
                return False
        return True
